const accounts = [
  { id: "975543647768982", name: "Livetransparent" },
  { id: "24843211111954088", name: "Livetransparent-2" },
  { id: "2186975138800404", name: "Livetransparent-3" }
];
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const dateStr = yesterday.toISOString().slice(0, 10);
return accounts.map(function(a) {
