const prepData = $("Prepare Requests").all();
const output = [];
for (var i = 0; i < $input.all().length; i++) {
  var item = $input.all()[i];
  var json = item.json;
  var prep = (prepData[i] || {}).json || {};
  var ads = json.data || [];
  for (var j = 0; j < ads.length; j++) {
    var ad = ads[j];
    var actions = ad.actions || [];
    var leads = 0;
    for (var k = 0; k < actions.length; k++) {
      if (actions[k].action_type === "lead") {
        leads = parseInt(actions[k].value) || 0;
        break;
      }
    }
    output.push({
      json: {
        report_date: prep.reportDate,
        ad_account_id: prep.accountId,
        ad_account_name: prep.accountName,
        campaign_id: ad.campaign_id || "",
        campaign_name: ad.campaign_name || "",
        adset_id: ad.adset_id || "",
        adset_name: ad.adset_name || "",
        ad_id: ad.ad_id || "",
        ad_name: ad.ad_name || "",
        impressions: parseInt(ad.impressions) || 0,
        clicks: parseInt(ad.clicks) || 0,
        spend: parseFloat(ad.spend) || 0,
        leads: leads
      }
    });
  }
}
return output;

